mapper.select:
/* 대국민포털_게시물기본 목록 조회 (PstMapper.selectPstList) */ SELECT p.pst_sn ,p.bbs_id ,p.pst_ttl ,p.pst_cn ,p.pst_inq_cnt ,p.fix_yn ,p.wrtr_dept_nm ,p.mdfr_dept_nm ,p.rgtr_id ,DATE(p.reg_dt) as reg_dt ,p.vdo_url_addr as video_id ,p.mdfr_id ,p.mdfcn_dt ,ft.srvr_file_nm as thmb_file_nm FROM kids_own.TB_PP_M_PST p LEFT OUTER JOIN kids_own.TB_CA_E_FILE_TRSM ft ON ft.atch_file_group_id = p.thmb_id AND ft.atch_file_id = (SELECT MAX(f.atch_file_id) FROM kids_own.tb_ca_e_file_trsm f WHERE f.atch_file_group_id = p.thmb_id) WHERE p.bbs_id = #{bbsId}
AND p.pst_ttl LIKE '%' || #{searchWrd} || '%'
AND p.pst_cn LIKE '%' || #{searchWrd} || '%'
ORDER BY p.fix_yn DESC, p.reg_dt DESC

mapper.update:
/* 대국민포털_게시물기본 조회수 증가 (PstMapper.updtInqCnt) */
UPDATE kids_own.TB_PP_M_PST
SET pst_inq_cnt = COALESCE(pst_inq_cnt, 0) + 1
WHERE bbs_id = #{bbsId}		
AND pst_sn = #{pstSn}
